sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    var sinsei = current.sinsei_number;
    var hatureibi = current.hatureibi;
    var user = current.name;
    var sys_id = current.sys_id;
    current.oya_meisai = sys_id;

    var meisaiGr = new GlideRecord('x_1882833_organi_0_meisai');
    meisaiGr.addQuery('sinsei_number', sinsei);
    meisaiGr.addQuery('oya_meisai', sys_id);
    meisaiGr.addQuery('kenmu_number', 'NOT', '入力中');
    meisaiGr.addQuery();
    meisaiGr.query();
    meisaiGr.deleteMultiple();

    var shozokuGr = new GlideRecord('x_1882833_organi_0_shozoku');
    shozokuGr.addQuery('user_id', user);
    shozokuGr.orderBy('kenmu_number');
    shozokuGr.query();

    if (shozokuGr.next()) {
        var name = user.u_ukanji_name;
        var number = user.u_number;
        current.number = number;
        var str = '[' + hatureibi + ']' + name + '(' + number + ')';
        current.name_kanji = str;
        current.kenmu_number = "主務";
        current.yakui_kyuu = shozokuGr.yakui;
        current.shumu_kyuu = shozokuGr.bumon.bumon_name;
        current.kimuti_kyuu = shozokuGr.kinmuti;
        current.yakui_sin = shozokuGr.yakui;
        current.shumu_sin = shozokuGr.bumon.bumon_name;
        current.kimuti_sin = shozokuGr.kinmuti;

        var int = 1;
        while (shozokuGr.next()) {
            meisaiGr = new GlideRecord('x_1882833_organi_0_meisai');
            meisaiGr.initialize();
            meisaiGr.sinsei_number = current.sinsei_number;
            meisaiGr.kenmu_number = "兼務" + int;
            meisaiGr.yakui_kyuu = shozokuGr.yakui;
            meisaiGr.shumu_kyuu = shozokuGr.bumon.bumon_name;
            meisaiGr.kimuti_kyuu = shozokuGr.kinmuti;
            meisaiGr.yakui_sin = shozokuGr.yakui;
            meisaiGr.shumu_sin = shozokuGr.bumon.bumon_name;
            meisaiGr.kimuti_sin = shozokuGr.kinmuti;
            meisaiGr.oya_meisai = current.sys_id;
            meisaiGr.name_kanji = current.name_kanji;
            meisaiGr.insert();
            int++;
        }
        if (int != 4) {
            while (int <= 4) {
                meisaiGr = new GlideRecord('x_1882833_organi_0_meisai');
                meisaiGr.initialize();
                meisaiGr.sinsei_number = current.sinsei_number;
                meisaiGr.kenmu_number = "兼務" + int;
                meisaiGr.oya_meisai = current.sys_id;
                meisaiGr.name_kanji = current.name_kanji;
                meisaiGr.insert();
                int++;
            }
        }
    }

})(current, previous);
